/**
 * SVA example: Molten Earth Shield Toggle
 * An elemental shield (molten earth by default) wrapped around each selected token, drawn in two
 * layers so it surrounds the token. Also works with the fire, ice and eldritch web themes.
 * Run again to fade it out.
 *
 * Usage: select tokens, run. Change THEME / COLOR below.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

// Theme -> colours available in JB2A:
//   molten_earth: orange, dark_orange      fire: orange, blue, purple, dark_green, dark_purple
//   ice: blue, purple                      eldritch_web: dark_green, dark_purple
const THEME = "molten_earth";
const COLOR = "orange";
const VARIANT = "01"; // 01 or 03 exist for both layers
const SCALE = 1.6;
const FADE_MS = 1000;

const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Select at least one token.");
const below = `jb2a.shield_themed.below.${THEME}.${VARIANT}.${COLOR}`;
const above = `jb2a.shield_themed.above.${THEME}.${VARIANT}.${COLOR}`;
if (!SVA.db.has(below) || !SVA.db.has(above)) return ui.notifications.warn(`No JB2A ${THEME} shield in ${COLOR}.`);
const sceneId = canvas.scene.id;

for (const tok of tokens) {
  const name = `sva-${THEME}-shield:${tok.id}`;
  if (SVA.effects.list({ sceneId, name }).length) {
    await SVA.effects.end({ name, sceneId });
    continue;
  }
  const seq = SVA.sequence();
  seq
    .effect()
    .file(below)
    .attachTo(tok.id)
    .scaleToObject(SCALE)
    .layer("belowTokens")
    .fadeIn(FADE_MS, { ease: "easeOutCubic" })
    .fadeOut(FADE_MS, { ease: "easeOutCubic" })
    .persist(true)
    .name(name);
  seq
    .effect()
    .file(above)
    .attachTo(tok.id)
    .scaleToObject(SCALE)
    .fadeIn(FADE_MS, { ease: "easeOutCubic" })
    .fadeOut(FADE_MS, { ease: "easeOutCubic" })
    .persist(true)
    .name(name);
  await seq.play();
}
